export type PrimitiveId = 'askCheapLLM' | 'askSmartLLM' | 'askDecisionModel' | 'embed' | 'similaritySearch'
export type Difficulty = 'Simple' | 'Medium' | 'Hard'

export interface Approach { title: string; summary: string; body: string; primitives: PrimitiveId[] }
export interface Problem { slug: string; title: string; question: string; description: string; category: string; difficulty: Difficulty; think: string[]; approaches: Approach[] }
export type ProblemSummary = Pick<Problem, 'slug' | 'title' | 'category' | 'difficulty'>
export interface Primitive {
  id: PrimitiveId; name: string; capability: string; short: string; color: string; tint: string
  input: string; output: string; mentalModel: string; underneath: string
  useful: string[]; notUseful: string[]; caution: string; providers: string[]; exampleCode: string
}

